import{_ as r,a as l,b as o}from"./chunks/d04b9e131d1ea3ab1f92.BvKq2VcS.js";import{_ as a,C as i,o as s,c as n,j as e,a as h,E as m,a6 as c}from"./chunks/framework.CnPv4DE1.js";const A=JSON.parse('{"title":"工作的未来（掌握这个技能栈）","description":"","frontmatter":{"title":"工作的未来（掌握这个技能栈）","originalTitle":"The Future Of Work (Acquire This Skill Stack)","date":"2024-07-28","originalUrl":"https://thedankoe.com/letters/the-future-of-work-acquire-this-skill-stack/","minutes":33,"sourceHash":"a97cb556d4a6195e059f6b6c7b6df4d4ff59c8264be9fc7d976c78ced157e321","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-work-acquire-this-skill-stack/"}]]},"headers":[],"relativePath":"letters/the-future-of-work-acquire-this-skill-stack.md","filePath":"letters/the-future-of-work-acquire-this-skill-stack.md"}'),u={name:"letters/the-future-of-work-acquire-this-skill-stack.md"};function g(f,p,d,k,b,q){const t=i("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"工作的未来-掌握这个技能栈",tabindex:"-1"},[h("工作的未来（掌握这个技能栈） "),e("a",{class:"header-anchor",href:"#工作的未来-掌握这个技能栈","aria-label":'Permalink to "工作的未来（掌握这个技能栈）"'},"​")],-1)),m(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/RS9qrdJLdmU?si=-mbnA-zJ6zG-ojtp" target="_blank" rel="noreferrer">观看原文视频</a></p><p>2022年，埃隆·马斯克（Elon Musk）以440亿美元收购了Twitter。</p><p>没过多久，他解雇了Twitter 80%的员工。那是多达6000多人的规模。</p><p>这并不是科技行业裁员或普遍裁员的唯一案例。新闻头条充斥着公司决定裁员的消息，剥夺了人们的生计，让普通大众终日惶恐，担心自己是不是下一个被开刀的人。</p><p>除此之外，还有一些其他有趣的预测。</p><ol><li>自2020年以来，自由职业者在劳动力中的比例已从36%跃升至46.6%。</li><li>预计到2028年，创作者（creator）经济的规模将翻倍，从2500亿美元增长至4800亿美元。</li><li>知名人士预测AGI——即通用人工智能——将在今年年底前实现。</li></ol><p>不过，也有人说，由于成本高昂，发展正在放缓，可能还需要两年或更长时间才能实现AGI。</p><p>无论如何，不管我们能活到500岁，还是在未来4个月或10年内让机器人替我们干家务，唯一的出路就是把命运掌握在自己手中。而这本来就是你一开始就该做的事。</p><p>难怪人们如此担心被取代。</p><p>他们的技能正在过时。他们正处于失去生存手段的边缘。他们的家庭、生活方式以及寻找新工作的能力都受到了威胁。</p><p>这一切都说得通。</p><p>至关重要的是，我们要明白这3个关键点。</p><p>理解它们将有益于你的未来，哪怕它们现在并不直接适用于你。</p><h3 id="_1-初级岗位正在走向消亡。" tabindex="-1">1) 初级岗位正在走向消亡。 <a class="header-anchor" href="#_1-初级岗位正在走向消亡。" aria-label="Permalink to &quot;1) 初级岗位正在走向消亡。&quot;">​</a></h3><p>获得一份初级工作正变得越来越难。</p><p>无论是编程还是营销，AI都能（或非常接近能够）在大多数领域执行基础的专业工作。</p><p>现在，这并不一定意味着初级岗位就此消失；这只是意味着门槛被提高了。</p><p>过去被算作初级职位的，现在已经成了中级——而且很快就会成为高级——级别的职位。</p><blockquote><p>软件开发人员的悲惨结局。</p><p>这话我一直说了6年。</p><p>10年后，90%的软件开发人员将无法拿到以前的薪资水平（经通胀调整后）。</p><p>解决方案：尽快成为一名独立开发者。</p><p>即使失败了，你也会学到以后能被大公司雇用的软技能。 <a href="https://t.co/TXVpHtYA41" target="_blank" rel="noreferrer">pic.twitter.com/TXVpHtYA41</a></p><p>— John Rush (@johnrushx) <a href="https://twitter.com/johnrushx/status/1806682114290541049?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 28, 2024</a></p></blockquote><p>现有的劳动力大军将由具备某些特质的、高技能且高薪的个体组成。</p><p>那么，这些“高技能”个体拥有什么你所不具备的特质呢？</p><p>新手该怎么做才能赚到钱？</p><p>开发人员、作家、营销人员、销售员、设计师，以及其他创意和技术工作者该如何生存？</p><h3 id="_2-人们并未受到真正的教育。" tabindex="-1">2) 人们并未受到真正的教育。 <a class="header-anchor" href="#_2-人们并未受到真正的教育。" aria-label="Permalink to &quot;2) 人们并未受到真正的教育。&quot;">​</a></h3><blockquote><p>如果你不为自己创造一个目标，别人就会给你分配一个。——《专注的艺术》（The Art Of Focus）</p></blockquote><p>只有奴隶才会被指望一生只做一项工作。</p><p>他们被教授特定职业的技能，比如种小麦、放羊、骑马。</p><p>我们当前的教育系统反映的正是对奴隶的教育。</p><p>今天，我们被教导要成为有用的工人。</p><p>我们被教导要服从权威。</p><p>我们被条件反射地训练成出于对惩罚的恐惧而去争取好成绩。</p><p><strong>一个自由人理应拥有目标，并去学习实现该目标所需的一切。</strong></p><p>目标是一个能对他人产生积极影响的宏愿。</p><p>大多数人不会选择自己的目标。他们从小就被植入了员工心态的程序，只会听命行事，并且只在那个狭窄的领域里学习。</p><p>目标意味着为了解决阻碍你实现目标的难题，你必须去学习知识和技能。</p><p>如果你不选择自己的目标，你就无法选择去学什么，也无法选择去解决什么问题。<em>你的心智在默认情况下就会保持狭隘，因为目标本来就很狭窄。</em> 你的命运是由别人为你决定的，因为你唯一知晓的潜力就是别人指派给你的那个。</p><p>那么，我们该学什么？</p><p>我们该如何保护自己免受AI威胁？</p><h3 id="_3-工作的未来属于一人企业。" tabindex="-1">3) 工作的未来属于一人企业。 <a class="header-anchor" href="#_3-工作的未来属于一人企业。" aria-label="Permalink to &quot;3) 工作的未来属于一人企业。&quot;">​</a></h3><blockquote><p>这个星球上差不多有70亿人。我希望有一天，能有差不多70亿家公司。——纳瓦尔（Naval）</p></blockquote><p>商业实体（公司）是一种法律结构，它允许你：</p><ol><li>打造你想要的东西</li><li>解决有价值的问题</li><li>从中获利</li></ol><p>我为什么要告诉你这些？</p><p>因为我已经受够了人们认为“做生意”或“创业”是那些有启动资金或拥有特定性格的人的专属专利。</p><p>在我看来，别再把赚取独立收入看作是“创办一家公司”了。把它看成是：让自己变得有价值，将这份价值打包，并参与价值交换——这种行为从山洞人时代就存在了，而不是直到法律规定出现时才有的。</p><p>社交媒体、创作者经济和现代科技已经让单个个体能够吸引并变现受众群体，这就相当于拥有一条分发渠道。</p><p>这不是什么赶时髦的新商业模式，这是现代世界的现实。</p><p>你有能力在互联网上学习任何东西，在互联网上打造任何东西，并从互联网上的任何人那里接受付款。</p><p>是的，你完全可以从0资产起步。</p><p>我们还有很多要讨论的，因为我们现在才刚刚铺设好背景。</p><p>以下是你在接下来的章节中将学到的内容：</p><ol><li>成为深度的通才将如何为你自己的未来保驾护航。</li><li>为了靠你的任何兴趣或热情谋生，你必须学习哪些技能（以及如何快速学习它们）。</li><li>为什么AI并没有你想象的那么特别，并且只会取代那些活该被取代的人。</li><li>如何将自己变成一人企业，以便你把命运掌握在自己手中。</li><li>如何在平均每天只工作4小时做自己想做的事的同时，实现从0到10万美元，再到100万美元的跨越。</li></ol><p>在历史上的任何其他时期，这些都是不可能实现的。</p><p>欢迎来到工作的未来。</p><h2 id="面向未来的技能栈" tabindex="-1">面向未来的技能栈 <a class="header-anchor" href="#面向未来的技能栈" aria-label="Permalink to &quot;面向未来的技能栈&quot;">​</a></h2><blockquote><p>传统教育和过度专业化是一种让人们屈从于主导范式/系统的方式。要去研究自然界普遍的底层原理，做一名深度的通才。——丹尼尔·施马滕伯格（Daniel Schmachtenberger）</p></blockquote><p>我想向你介绍一位公认的天才、发明家兼哲学家。他设计了测地线穹顶（geodesic dome），这种结构极其稳定同时又非常轻巧，彻底颠覆了建筑设计。</p><p>他的名字叫巴克敏斯特·富勒（Buckminster Fuller）。</p><p>在他的著作《地球宇宙飞船操作手册》（Operating Manual For Spaceship Earth）中，他用“大海盗”（The Great Pirates）作了一个比喻。</p><p>大海盗们名副其实就是海盗，他们精通许多事物，比如地理、天文导航、生物学、他们船上的手下、船只本身、历史和科学，因为这些都是在贸易和统治中取得成功必不可少的学科。</p><p>他们带上船干活的手下是故意被培养得很蠢的。海盗们不想让他们理解自己的策略，以免他们图谋篡权夺走财富。这些手下只被期望毫无疑问地服从命令，而他们也确实照做了。</p><p>海盗们拥有全球性的知识，因为他们可以航行到不同的陆地。他们是通才。而陆地上的统治者只了解他们的领土以及海盗告诉他们的事情（而且海盗还会撒谎）。统治者则是专才。</p><p>这赋予了海盗巨大的权力，使得陆地统治者在贸易和知识上不得不依赖他们。</p><p>海盗们忽悠陆地统治者，让他们把享有声望的职位赐予王国里最聪明的人，以此让他们保持思维狭隘。他们会给这些聪明人诸如“皇家历史学家”或“财政大臣”的头衔，让他们成天研究那一个细分领域（niche），导致他们只对陆地统治者和海盗有用。就像海盗船上的水手一样，这防止了陆地上的聪明人推翻海盗，因为他们是专才，而不是通才。</p><p><em>聪明人满足于这份声望。</em></p><p><em>陆地统治者满足于有“聪明”人为他们效劳。</em></p><p><em>海盗们满足于跨越多片陆地将两者玩弄于股掌之间。</em></p><p>这里的教训是：</p><p>学校的创建初衷是通过承诺专业化的声望来奴役最聪明的人。这样一来，他们就会保持思维狭隘，不去选择自己的目标，因此也不会去学习多门兴趣和技能——而这本可以让他们去推翻那些为他们指派目标的人。</p><p>这就解释了为什么专业化今天仍然备受推崇。这就解释了为什么当青少年思考未来的出路时，脑子里蹦出的第一件事就是“高薪工作”。</p><p>你被植入的程序，注定就是为了让你被取代的。</p><p>让我们来学学如何逆转已经造成的伤害。</p><h3 id="如何成为一名深度的通才" tabindex="-1">如何成为一名深度的通才 <a class="header-anchor" href="#如何成为一名深度的通才" aria-label="Permalink to &quot;如何成为一名深度的通才&quot;">​</a></h3><blockquote><p>什么都去尝试一下。</p><p>成为作家、设计师、营销员、电影制作人、健美运动员、跑步者，或者任何你的好奇心所向往的角色。</p><p>互联网赋予了个体快速学习几乎任何事物的能力，并能从多样的兴趣中结出硕果。</p><p>你正在经历第二次文艺复兴。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1788225509593149750?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 8, 2024</a></p></blockquote><p>动物和人类的区别在于，动物通过专业化，或者说向着越来越细的细分领域进化，来求得生存。</p><p>问题在于，过度专业化会导致某些物种灭绝。</p><p>就像长嘴鸟能够捉到浅水里的鱼，所以它们就呆在那种环境里。然后，它们繁衍后代，鸟嘴最长的存活了下来，但后来鸟嘴变得实在太重以至于它们无法飞翔，而孩子们的嘴变得太小，以至于没有任何食物留给他们了。</p><p>另一方面，人类通过制造工具来弥补自身的不足。</p><p>过去，我们学会掷长矛以便能有口饭吃。今天，我们学会在手机上给社交圈发信息，以免被视为异类。你周围所有的技术进步，曾经都是为了防范人类灭绝而建立的屏障。</p><p>这里有一个问题：</p><p>你正在打造什么有价值的东西，来防止自己被取代吗？</p><p>还是说，你甘愿靠着单一的技能充当别人机器里的一颗齿轮，坐在那儿等着被淘汰？</p><p>人类天生就是通才。他们在互相重叠的细分领域的交汇处繁衍生息，并能通过打造工具、掌握新技能或学习新信息来适应全新的领域。</p><p>我想确切地告诉你，要成为一名深度的通才，你到底该学些什么。</p><p>我接下来要分享的是一个技能栈，从大局观到技术细节，它们将让你能够自己做决定、独立思考，并确保你未来的安全。</p><p>在德文·埃里克森（Devon Eriksen）看来，七种文科（或者他造的一个词——“解放学科 [liberating arts]”，因为它们与那些文理学院里教授的几乎毫无价值的信息大相径庭）分别是，我引用一下：</p><ul><li><strong>逻辑学</strong>：如何从已知事实中推导出真相</li><li><strong>统计学</strong>：如何理解数据的含义</li><li><strong>修辞学</strong>：如何说服他人，并识破说服策略</li><li><strong>研究</strong>：如何收集关于未知主题的信息</li><li><strong>（实用）心理学</strong>：如何洞察和理解他人的真实动机</li><li><strong>投资</strong>：如何管理和增加现有资产</li><li><strong>能动性</strong>：如何决定追求的方向，并积极采取行动去追求它。</li></ul><p>如果你想学习这些技能，在你潜入未知领域时，必须将它们牢记于心。</p><p>如果你用具备抗未来风险能力的头脑武装自己，那么无论你认为未来哪些技术技能会赚钱或有用，都无关紧要，因为你可以根据需要进行调整。</p><p>为了学习这些解放天性的技艺，我掌握了以下技能：</p><ul><li><strong>营销与销售</strong> – 如果你不知道如何吸引和说服他人，你将永远无法得到你想要的东西，你唯一的选择就是等待雇主（或政府）施舍给你。（修辞学、心理学）</li><li><strong>写作与思考</strong> – 传达你独特思想价值的能力。这是在众人面前脱颖而出的基础。（逻辑学、研究）</li><li><strong>创业</strong> – 将未来掌握在自己手中，为生存而狩猎，并打造出我希望在这个世界上看到的（同时也是别人关心的）产品的过程。（统计学、能动性、投资）</li></ul><p>创业可能不是一种“技能”，但它是一种元技能。它教你具备高能动性、识别问题、销售解决方案、系统化你的工作，并培养让你变得无法被雇佣（不再适合打工），从而变得不可替代的其他特质。</p><p>现在，没有人能告诉你该如何写作、思考、营销和销售。他们只能告诉你<em>他们</em>是怎么做的。</p><p>这意味着，要学习这些技能，你必须拥抱自我实验的心态。</p><p>你的工作是：</p><ul><li><strong>研究别人已经取得成功的流程。</strong> 读书，使用谷歌搜索，狂刷YouTube教程。自我教育必须成为每天30-60分钟的习惯。这没得选。</li><li><strong>尝试各种技术。</strong> 实施你学到的流程，并试着取得成果。</li><li><strong>识别模式和原则。</strong> 注意它们之间的相似之处并加倍投入。</li><li><strong>创建你自己的流程。</strong> 将你学到的东西量身定制，以适应你独特的生活方式和处境。</li><li><strong>通过传承来为真正的教育做出贡献。</strong> 传授人们学校里教不了的教育，并以批判性思维为根本。</li></ul><p>以创业为载体，你为真正的教育和自主权搭建了舞台。</p><p>通过写作和思考，你不断创造、测试并迭代你所能提供的价值。</p><p>你必须学习实用心理学——营销和销售——来理解你自己和客户的内心。</p><p>然后你去说服，而不是强迫或欺骗，去激发人们关注你所能提供的价值。</p><h3 id="技术诀窍与个人兴趣" tabindex="-1">技术诀窍与个人兴趣 <a class="header-anchor" href="#技术诀窍与个人兴趣" aria-label="Permalink to &quot;技术诀窍与个人兴趣&quot;">​</a></h3><p>在拥有了抗未来风险的技能栈基础之后，下一步就是用技术技能来适应时代。</p><p>在这场数字复兴中，这意味着：</p><ul><li><strong>社交媒体</strong> – 为自己扬名，作为你创造价值的店面。这是你的业务指挥中心。</li><li><strong>内容</strong> – 通过写作、设计或视频来教育、娱乐和启发人们看到你的价值。</li><li><strong>电子邮件营销</strong> – 使用新闻通讯或自动化邮件序列来培育你获得的受众。</li><li><strong>视觉设计</strong> – 描绘你品牌的氛围，以激发受众的情感。</li><li><strong>漏斗构建</strong> – 创建落地页、网站，并通过内容和电子邮件等其他技术技能为它们注入燃料。</li></ul><p>随着人工智能震撼整个行业，学习这些技能的要求注定会发生变化。它们短期内不会消失，但由于获取这些技能变得更加容易，总体竞争将会加剧。</p><p>如果你只学习这些技能，而<em>没有</em>学习前面的营销、销售、写作和创业，这些技能就会失去威力。</p><p>这些技术技能是你作为创业者开始打造自己事业的方式。</p><p>现在你要问的问题是：</p><ul><li>我该写些什么？</li><li>我该营销和销售什么？</li><li>我发什么邮件、做什么设计，或者说我把技术技能这个杠杆用在什么上？</li></ul><p><em>那些你忍不住想告诉别人的兴趣。</em></p><p>那些你欲罢不能的书籍。</p><p>那些淹没你搜索历史的想法。</p><p>那些你梦想构建，却似乎找不到——抱歉，是<em>挤不出</em>——时间去构建的项目。</p><p>如果你想获得我关于写作或打造产品的系统，你可以在<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">我的网站</a>上找到“2小时写手”（2 Hour Writer）和“心智变现”（Mental Monetization）。</p><p>你就是最赚钱的细分领域。</p><p><img src="'+r+'" alt=""></p><p>创作者经济（Creator Economy）——不要与网红经济混淆——其特征是个人追求自己的兴趣并记录自己的知识。</p><p>创作者通过自己的愿景、故事和目标来吸引受众。AI是没有好奇心的。你必须给它愿景、故事或目标的上下文，它才能工作。好奇心和通才能力是你吸引那些志同道合、且正面临你已解决过的问题的人的优势。</p><p>商业和价值就是解决问题。这就是你赚钱的方式。</p><p>没有人想去关注一个整天只会喋喋不休谈论同一个话题、被美化过的搜索引擎。</p><p>许多创作者告诉我，他们害怕涉足新的兴趣。他们搞不懂这怎么能行得通。</p><p>你只需要看看你关注的所有人。他们真的只谈论<em>一</em>件事吗？真的吗？</p><p>还是说，他们把自己的观点、信念、知识和生活经验的片段打包成具有影响力的内容？</p><p>“但是 Dan，那我该卖什么呢？”</p><p>我们很快就会谈到这个，别担心。</p><p>你不能“找到”一个赚钱的细分领域。你通过说服创造一个赚钱的细分领域。你写出具有说服力的论点，说明为什么你的兴趣能造福他人的生活，你销售与该兴趣一致的产品，并通过社交媒体、电子邮件和设计等技术技能来交付这两者。</p><p>如果你理解了那些抗未来风险的技能，进而理解了人性，你就会明白，你可以控制别人对你兴趣的看法。</p><p>兴趣是被制造出来的。兴趣是被编程设定的。你之所以对特定事物感兴趣，是因为你的成长方式以及你所接触到的信息。</p><p>你对它们感兴趣是有原因的。这意味着别人也可以通过社交媒体上恰到好处的文案，<em>变得</em>对它们感兴趣。这以前就在你身上发生过。去刷刷你的时间线，然后告诉我没有什么是能说服你改变行为的。</p><p>你把时间、注意力和金钱花在你的兴趣上。这意味着如果你足够有价值，别人也会把同样的资源花在你身上。</p><p>自由的人不会把自己局限在细分领域里。</p><h3 id="但是人工智能呢" tabindex="-1">但是人工智能呢？ <a class="header-anchor" href="#但是人工智能呢" aria-label="Permalink to &quot;但是人工智能呢？&quot;">​</a></h3><p>让我们做一个思想实验。</p><p>你是一名创业者，而不是一名员工。</p><p>你在有生之年想打造出多个产品，无论是在退休前还是在死前（因为你已经发现退休是一种幻觉，工作是休息必要的平衡，如果我们从不工作，我们会很痛苦。我们只是在做错误的工作而已）。</p><p>为了构建这些产品，你需要：</p><ul><li>一个为理想客户提供使命、愿景和哲学的品牌。</li><li>写作、演讲、广告、视频、设计和电子邮件，以吸引和培育客户。</li><li>一个具有说服力的营销信息，帮助你在众人中脱颖而出。</li><li>一个根据反馈不断迭代的产品。</li><li>以及更多，这些都会在你计划打造的所有产品中重复应用。</li></ul><p>现在人们在社交媒体上常问的问题是这样的：</p><p><em>“如果 AI 能写落地页或学期论文，写手会被取代吗？”</em></p><p><em>“如果 AI 能开发应用，程序员会被取代吗？”</em></p><p>答案是：是的，其中一部分会，如果他们无法掌控愿景的话。</p><p>计算机是超级专家。人类是深度通才。这是一个很棒的组合，但单打独斗都不太有效。</p><p>计算机只会取代那些活该被取代的人。</p><p>AI 可以帮助你<em>更快地</em>写学期论文、创建设计或剪辑视频，赋予使用 AI 的个人更多力量，并让价值1000万美元的一人企业成为可能，但仍然需要有一个人来主导通往未来愿景的道路。</p><p>担心被取代的人一个根本性的误解是，世界上总有未解决的问题。你不知道如何去狩猎。你被困在别人分配的一连串重复性的已知任务中。你为什么会成为被取代的首选，答案显而易见。你不成长，也不进化。没有新意，没有迭代，也没有朝着愿景去构建事物，这种停滞不前的状态让你根本无从发现那些本可以去解决的问题。</p><p>如果你依赖别人给你一个问题去解决，你就会被取代。</p><p>你需要目标、能动性和创造力。</p><p>AI 可以写一本书，但它必须隶属于一个更大的目标才有价值：这本书是为了某个受众群体而写，被推销和分发给他们，并经过说服让他们觉得这本书有价值。</p><p>试着让 AI 给你写本畅销书吧。</p><p>我会等……等上一阵子……因为畅销书不仅仅关乎写作本身。</p><p>你需要钩子，需要与有分发渠道的公司、品牌和创作者建立联系。而这仅仅是冰山一角。</p><p>在此期间，用 AI 更快地完成你的打工活儿，这样你就有时间抽身了。</p><p>我已经知道你要问什么了。</p><p>我该干点什么才能抽身呢？</p><h2 id="将自己产品化-——-一人企业模式" tabindex="-1">将自己产品化 —— 一人企业模式 <a class="header-anchor" href="#将自己产品化-——-一人企业模式" aria-label="Permalink to &quot;将自己产品化 —— 一人企业模式&quot;">​</a></h2><p><em>如果你解决过生活中的某个问题，你就有资格创业。</em></p><p>不只是随便什么生意。</p><p>是一门教育生意。</p><p>作为单枪匹马的一人。</p><p>带着零启动成本。</p><p>用你脑子里已经拥有的知识（不管你的经验水平如何）。</p><p>大多数人试图建立一个“初创公司”，或者是他们在跟朋友喝了一晚酒后想出的某个疯狂点子。</p><p>他们觉得自己的想法能改变世界，但这通常是妄想，因为他们之前根本没有任何商业经验。</p><p>如果这是你在零经验下想出的主意（意味着你的脑子里只有这几个还过得去的想法……你没有打造过任何能引出更好点子的东西），那我几乎可以保证，肯定已经有人尝试过并且失败了。</p><p>当然也有特例，但在这里最好不要寄希望于运气。</p><p>人们通过解决健身、生产力、职业、金钱、人际关系和生活方式问题赚了几百万，这是有原因的：</p><p>因为每个人都有这些问题。</p><p>因为 AI 可以帮助传播工具和知识，但它实际上无法改变个人的行为。这正是来自志同道合的个人（创作者）的写作、信息、系统和产品通过教育所能做到的事情。</p><p>因为这些问题阻碍了普通人去做他们唯一想做的事情……享受生活。</p><p>还有什么比解决<em>你</em>每天都在经历的问题更好（且更赚钱）的呢？</p><h3 id="每天工作4小时-从0到100万美元" tabindex="-1">每天工作4小时，从0到100万美元 <a class="header-anchor" href="#每天工作4小时-从0到100万美元" aria-label="Permalink to &quot;每天工作4小时，从0到100万美元&quot;">​</a></h3><blockquote><p>让我们把一人企业这整件事变得简单点：\\</p><ol><li>为自己建设\\</li><li>写给曾经的自己\\</li><li>卖给曾经的自己\\</li></ol><p>世界上有数百万人与你有同样的兴趣、问题和渴望——而你只需要找到他们中的一小部分。\\</p><p>最赚钱的细分领域就是你。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1583750513862098945?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 22, 2022</a></p></blockquote><p>如果你在健身方面取得了成果，就卖健身计划。</p><p>如果你在保持专注力方面取得了成果，就卖生产力课程。</p><p>如果你在某项技能上取得了成果，就卖教程。</p><p>如果你在心理学应用上取得了成果，就卖日记提示词。</p><p>如果你在灵性修习上取得了成果，就卖冥想指南。</p><p>这样的例子不胜枚举。</p><p>你可以看到人们每天都在靠做自己热爱的事情谋生，因为这是仅存的少数不可替代的道路之一。人工智能正在解决人类不想解决的问题，留给我们的只有一个选择：享受生活，并通过运用我们独特的天赋为人类做出贡献来寻找意义。</p><p>“Dan，现在每个人都在卖信息产品……这看起来像个骗局。”</p><p>又是这种狭隘的视角。你没有足够的经验来理解这个行业。你不明白信息和教育是<em>一切</em>的基础。学习是人类体验的基础，而大多数人的体验并不怎么好，主要就是因为他们不教育、不提升自己。</p><p>相比于敞开心扉去改变生活，你的第一反应是一种程序化的条件反射，封闭思想，原地踏步。你不想改变，这很明显，但至少在这点上你要对自己诚实。</p><p>这也说明你不懂商业入门的第一课：卖那些已经在卖的东西。特别是当你刚起步时。不要去追逐蓝海，钱没有流向那里是有原因的，而且你并不比大自然更聪明。</p><p>学校系统正在失效。</p><p>教育是人类的基础。</p><p>创作者就是去中心化的学校系统。</p><p>你不停地抱怨“[填入任何现实世界的问题] 应该在学校里教！”</p><p>而现在网上确实有人在教了，成本只是正规教育的一小部分（甚至免费），你却管这叫骗局。</p><p>唯一真正的骗局是，在学校之外有如此多可用信息的情况下，你却不对自己的未来负责。</p><p>在我看来，一人企业是为那些看重自力更生、时间自由和地点自由的人准备的。</p><p>我们利用：</p><ul><li>社交媒体来建立杠杆，吸引志同道合的人，并（从零开始）为自己打响名气</li><li>无代码工具和软件来建立数字资产、产品托管和电子邮件列表（这些不会像社交媒体账号那样被夺走）</li><li>生活方式设计来创造最适合个人的工作时间表——通常刚开始每天工作2-4小时，有时如果你进入了心流状态，时间会更长</li></ul><p>能够生活在这个时代令人难以置信。</p><p>互联网赋予了每个人成为企业家的能力，让他们可以选择自己的工作时间，并围绕自己痴迷的事物赚取收入。</p><p>没有两个人会痴迷于现实的同一个缝隙。随着你的进化和经历的增加，没有两个人会痴迷于他们（通过行动和实践）所察觉到的那个现实缝隙。</p><p>只要做法正确……就不存在饱和这回事。</p><h3 id="零经验启动一人企业的3条路径" tabindex="-1">零经验启动一人企业的3条路径 <a class="header-anchor" href="#零经验启动一人企业的3条路径" aria-label="Permalink to &quot;零经验启动一人企业的3条路径&quot;">​</a></h3><p>最大的杀手在于，人们不相信商业适合他们，或者觉得自己没有足够的经验。</p><p>首先，不要把商业想得太复杂，它只不过是价值交换。企业是一个法律结构，用来构建你想要的东西。我们的祖先也有生意，只是他们不需要一个法律结构来进行价值交换。你得到一些有用的东西，我也得到一些有用的东西。如果你想在这个围绕金钱运转的世界里真正有所作为，就放下你那高尚的慈善做派。<em>为了自我感觉良好而表现得无私，只是另一种自私。</em></p><p>如果你曾经用你一生中学过的<em>任何</em>知识帮助过你的朋友或家人，你就有了足够的经验。</p><p>更进一步想，你认为经验是怎么来的？</p><p>我告诉你一件事，如果你不踏入竞技场，你<em>永远不会</em>获得经验。你是通过在现实世界的环境中练习你的技能来获得经验的。</p><p>如果一个自由职业者能在零经验的情况下联系客户（为了<em>获得</em>经验）以换取金钱，为什么你不能在网上发布一些有价值的东西且不求任何回报呢？</p><p>你自己觉得这说得通吗。</p><p>你的冒名顶替综合征纯属自欺欺人。</p><p>如果有帮助的话，不要把你的写作当成是教学。人们自然而然会受到教育。相反，把它看作是公开做笔记，或者分享对你影响最深的观点。有着不同目标和性格的人会觉得不同的观点有影响力，所以，只要分享你的想法，你就是独一无二的，因为你的大脑是这个星球上最独一无二的东西。</p><p>以下是你可以选择的2条路径：</p><p><strong>路径1：基于技能</strong></p><p>这是人们告诉你要走的最常见的路线。</p><ol><li>学习一项技能</li><li>教授这项技能</li><li>出售这项技能</li></ol><p>这很好，但正如我所说，你不会想最终变成一个单维度的人。你不想成为无法规模化的客户工作的奴隶。你不想在追求其他事情时一无所获。这种情况经常发生。自由职业者通过冷邮件和内推赚取收入，而当人类本性开始发挥作用、你想要改变方向时，你又得<em>从零</em>开始了。</p><p>你可以从自由职业者开始，但你应该积累相当多元化的受众，既为了获得客户，也为了在你有足够的分发渠道时能从中转型。</p><p><strong>路径2：基于发展</strong></p><p>这第二条路线更符合我的节奏。</p><p>它围绕着四大永恒市场。</p><p>这四大永恒市场是存在迫切且有利可图的问题的地方。在那里，人们有着你可以帮他们实现的崇高目标。</p><ul><li>健康</li><li>财富</li><li>人际关系</li><li>幸福</li></ul><p>人工智能无法解决人类的问题。它可以给我们提供工具，但它治愈不了我们因意识失序而产生的意义匮乏、缺乏清晰度等其他内在特质缺失。我们正在进入一个目标/人性经济时代，在这个时代，我们超越了基本需求，拥有足够的心理能量去关注我们的成长需求——挑战、理解和意义。</p><p>路径1只关注财富。传授有市场需求的技能来帮人们赚更多钱。默认情况下，你建立的是一个单维度的品牌。</p><p>有了路径2，你完全是在追求你自己的人生目标（品牌），在追求这些目标的过程中解决你自己的问题（内容），并创造一个系统来帮助他人做同样的事（产品）。</p><p>这就是你如何做自己、提升自己并从自己身上获利的方式。</p><p>“但是Dan，我才刚起步啊！”</p><p>所以呢？</p><p>又不是非得让你写“我如何在3天内赚了100万美元”的内容。如今关心这个的人越来越少了。他们会在脑海里把它判定为骗局。</p><p>品牌和内容全看视角。或者说营销中的“定位”。你要做的只是保持诚实。</p><p>哪个效果会更好？</p><p>“我如何在3天内赚了100万美元”</p><p>还是</p><p>“我计划如何在5年内赚到100万美元”</p><p>你会点击哪一个？你会关注哪一个？你对哪一个最有共鸣？你会<em>相信</em>并亲自实践哪一个？</p><p>自我意识和行为改变是你品牌成功的重大决定因素。你是否意识到作为局外人，你自己会如何看待你的品牌或内容？你发布的内容真的能改变人们的生活吗？</p><p><strong>路径3：两者结合</strong></p><p>一人企业的美妙之处在于，你被迫成为一个通才。</p><p>你<em>必须</em>学习让任何企业取得成功的所有技能。在默认情况下，你就具备了抗拒未来淘汰的能力。</p><ul><li>设计你的网站、头像和横幅</li><li>说服力与营销，用于你的个人简介、内容和网页</li><li>销售你的产品、服务和拓展人脉</li><li>运营，通过将整个流程系统化，缩减到每天只需几个小时的工作</li></ul><p>当然还有写作，这是任何商业成功的基础技能（也是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>中所教授的）。你要把它用于内容、电子邮件、新闻通讯、广告、视频脚本以及几乎所有事情……因为说到底，你只是在电脑前打字来建立这个事业。</p><p>为什么这很美妙？</p><p>因为你通过谈论你的兴趣和目标来积累受众。通过积累受众，你就拥有了可以向他人收费的市场化技能。你还有了一群感兴趣的受众，他们准备好付费购买与你实现相同目标的方法。换句话说，你可以用不止一种方式将你广泛的技能或知识变现——这非常强大。</p><p>举个例子，Jose Rosado靠卖个人主页横幅赚到了全职收入，然后转型做网页设计，赚了数十万美金。接着又转型做数字产品。一人企业的商业模式利好你的个人进化。正是这一点让你与众不同。</p><p>如果你没看到机会，那是因为你不在竞技场里。机会无法进入你的认知，因为你陷入了“教程地狱”，而没有去经历3到6个月的开始、失败和进步。</p><p>生活中任何美好事物的入门门槛，都是半年的失败。</p><h3 id="一人企业的四大支柱" tabindex="-1">一人企业的四大支柱 <a class="header-anchor" href="#一人企业的四大支柱" aria-label="Permalink to &quot;一人企业的四大支柱&quot;">​</a></h3><p>对于那些想做<em>自己想做的事</em>、并帮助那些<em>自己最能帮到的人</em>的人来说——传统的品牌、营销、内容和报价创造会将你引向错误的方向。</p><p>个人品牌是我们这个时代最强大的门面。它建立了人与人之间的连接。</p><p>传统的商业模式会让你根据那些拥有你可以解决且有利可图的问题的人，来创建一个客户画像。</p><p>我的方法，即“体验模型”，将“你”变成了客户画像。你的经历和故事把你变成了细分领域。</p><p><img src="'+l+'" alt=""></p><p>这样一来，你就可以解决自己的问题，吸引那些与你在相似道路上的人，并帮助他们做同样的事。</p><p>另一个好处是，你不需要花费数不清的时间做市场调研来弄清楚什么好卖。</p><p>明白我的意思了吗？</p><p>你追求一个目标，实现它，谈论它，吸引有同样目标的人，并为他们提供更快实现目标的解决方案（产品或服务）。这就是你获得收入的方式。你去帮助那些你最能帮到的人进步，但要比你当初进步得更快。</p><h3 id="支柱1-品牌" tabindex="-1"><strong>支柱1：品牌</strong> <a class="header-anchor" href="#支柱1-品牌" aria-label="Permalink to &quot;**支柱1：品牌**&quot;">​</a></h3><blockquote><p>在商业中，不要再试图寻找要去解决的“问题”了。\\</p><p>相反，去理解人们试图实现的“目标”。\\</p><p>然后，成为解决那些阻碍人们实现该目标的问题的专家。\\</p><p>帮助他们尽可能快地到达那里。那才是他们想要的。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1576922278700490753?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 3, 2022</a></p></blockquote><p>你的品牌就是你是谁，你做什么，以及你正在做什么。</p><p>你正在为实现什么<strong>目标</strong>而努力？</p><p>为什么你要为之努力？你试图实现的期望结果是什么？这就是人们会关注你的原因。</p><p>关于品牌，有一点是它不需要在很多地方直接声明。也许是在你的网站上，你可以在那里解释你的品牌信息，但除此之外——人们会通过你的内容领悟到你的品牌信息是什么。</p><h3 id="支柱-2-内容" tabindex="-1"><strong>支柱 2) 内容</strong> <a class="header-anchor" href="#支柱-2-内容" aria-label="Permalink to &quot;**支柱 2) 内容**&quot;">​</a></h3><p>新手需要明白这一点：</p><p>你的品牌（尤其是在社交媒体上）是通过1-3个月的内容形成的。</p><p>内容会产生复利。我指的不是浏览量或覆盖面的复利。我的意思是，信息会在人们的脑海中产生复利，直到你的完整信息让他们<em>恍然大悟</em>。</p><p>人们不会仅仅通过一条推文、一个视频或一篇文章就理解你。</p><p>如果你想拥有一丝一毫的权威，你在这个游戏里就需要时间。</p><p>那么，你要写些什么呢？</p><p>你写你计划掌握的兴趣、技能和话题。写那些能以你独有的方式帮助你实现目标的东西。</p><p>还记得上面提到的推文吗？关于不要寻找问题，而是设定目标的那条？</p><p>所有内容（以及普遍的人类注意力和行为）都围绕着问题展开。问题是你内容的起点，但你<em>和</em>你的粉丝必须在朝着相似的目标努力，这些问题才会变得<em>相关</em>。</p><p>每个人都可以拥有“过上好日子”这个共同目标，但<em>你</em>打算如何将其变为现实？</p><p>对我来说，是通过研究人类心理、哲学和创造性工作来实现的。</p><p>对另一个人来说，可能就是网页设计、心态和健身。</p><p>对再一个人来说，可能是自动化、营销和生产力。</p><p><em>如果你把5个人放在山脚下，问他们如何登顶，他们全都会画出不同的路线。</em></p><p>这些话题的独特组合<em>就是</em>你的细分领域。</p><p>它们很宽泛，因为我们想要建立一个庞大、有杠杆作用且灵活的受众群体——而不是把自己关在盒子里，限制我们能谈论的内容。</p><p>如果有一天我想转向健身领域，把我（摸索了多年）的训练方案变成一门课程，并把它卖掉赚钱，我是可以做到的。我会以最能吸引受众的方式向他们（跟我有着相似目标和兴趣的人）推销。</p><p>但是，你要<em>如何</em>写这些话题呢？</p><p>在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>中，我教授了“精通领域”（Domain Of Mastery）。</p><p><img src="'+o+'" alt=""></p><p>你选择3个<em>宽泛的</em>话题，然后可以将其分解为原则、提供灵感的导师以及子话题。</p><p>然后，你可以研究书籍、播客、文章和社交帖子，看看其他人是如何谈论这些话题的。</p><p>这不仅仅是生意。这就是你如何通过提升自己、学习如何思考以及创造有意义的生活来获得报酬的方式。</p><p>请理解，这只是让你<em>向前迈进</em>的起点。当你意识到一些你真正想做的事情时（因为在你之前的水平上，你并没有意识到它），你会进行转型。</p><p>在一开始，你的工作是模仿那些行之有效的东西。</p><p>你需要通过撰写能一次又一次保证增长的新手级内容，在你谈论的话题中建立权威。</p><p>去看看你最喜欢的YouTuber。</p><p>他们一开始是通过酷炫的vlog小视频来积累受众的吗？</p><p>还是说，他们把教育受众、向他们教授新技能和新兴趣作为了自己的全职工作？</p><h3 id="支柱-3-产品服务-offer" tabindex="-1"><strong>支柱 3) 产品服务 (Offer)</strong> <a class="header-anchor" href="#支柱-3-产品服务-offer" aria-label="Permalink to &quot;**支柱 3) 产品服务 (Offer)**&quot;">​</a></h3><p>不，你不需要等到以后才开始变现。我听腻了那种屁话（sh*t）。守门员心态。</p><p>你<strong>需要</strong>一些可以迭代的东西。你需要一些可以去构建、去改进、去让其变得更有价值的东西。</p><p>Offer（产品服务）就是你的产品或服务。它是人们用钱换取到的东西。</p><p>你的第一个Offer<strong>绝对会</strong>很烂。这是逃不掉的。你应该立刻把那第一个糟糕的迭代版本搞出来。</p><p><em>你无法改进不存在的东西。</em></p><p>你需要体验销售是什么感觉。你需要一个现实世界的载体，来应用你学到的所有营销和销售知识。</p><p>“好吧 Dan，但我该卖什么呢？”</p><p>让我向你介绍<strong>最小可行性Offer（Minimum Viable Offer）</strong>。</p><p>MVO 要么是：</p><ol><li>单一技能的自由职业服务，你可以卖到500-1000美元</li><li>单一兴趣/技能的咨询、教练或辅导服务，你可以把一个4次通话的套餐卖到500-1000美元</li></ol><p>如果你要加入创作者经济，我几乎总是推荐选项2。我不会从极其耗时的客户工作开始，那会让你觉得没时间创作内容。</p><p>（而且，如果你跟我一样，你会喜欢自己去学习和尝试。大多数——不是所有——创作者都是如此。我不喜欢别人替我干活）。</p><p>健康、生产力、心态和商业咨询是理所当然的热门选项。</p><p>但是，如果你想卖的是一项技能而不是兴趣，你依然可以这么做。你只需把它包装成“辅导”。</p><p>你可以辅导或指导人们如何建立网站。</p><p>你可以辅导或指导人们如何写作。</p><p>你可以辅导或指导人们如何开始电子邮件营销。</p><p>从MVO开始的美妙之处在哪里呢，尤其是如果它是一个包含2-4次咨询通话的套餐的话？</p><p><strong>1) 你可以立即开始变现。</strong></p><p>如果你了解销售流程，就不需要着陆页。能够给别人发私信（DM）、一个问卷软件、外加一个日历预订链接就够了。（当然还需要一个发送发票的方法）。</p><p>你参与通话，帮助人们解决他们的问题，并全身心投入去研究解决这些问题的有效方案。你不需要在一开始就有所有的答案，你只需要比对方有更多的时间。他们没有时间自己去解决问题。这就是为什么他们愿意为你的服务买单——为了速度、便利和担责。</p><p><strong>2) 你可以基于能产生结果的东西，打造出一款可规模化扩展的产品。</strong></p><p>为了提高你MVO的价值，你要勾勒出一种课程大纲，以此来帮助组织通话的结构。你还应该创建工作表和Notion仪表盘等资料，以帮助你的客户取得更多成果。</p><p>随着受众的增长，这些资料可以变成你可以出售的产品。产品买家后续可以被引流到你的咨询服务中，成为你的客户。</p><p>这意味着，如果你选择减少接纳的客户数量，你花在寻找潜在客户上的时间就会更少，拥有的空闲时间就会更多（当然，你的价格也会暴涨）。</p><h3 id="支柱-4-营销" tabindex="-1"><strong>支柱 4) 营销</strong> <a class="header-anchor" href="#支柱-4-营销" aria-label="Permalink to &quot;**支柱 4) 营销**&quot;">​</a></h3><p>想象一下你已经创建了自己的MVO。</p><p>你想推销编程辅导服务，教人们如何写代码。</p><p>现在，为了卖出那项服务，你需要建立权威和信任。</p><p>因此，你写了一份关于新手级编程话题的周报（以便覆盖更多的人，毕竟市场上90%的人都是新手）。</p><p>你结交编程领域的其他人进行人脉拓展，好让他们的受众看到你的内容。</p><p>如果你在推文长贴（thread）底部推广你的服务，并且你的长贴获得了超过10万次曝光（这算最低的了），你几乎肯定能拿下你的第一个客户。</p><p>砰，凭借正确的策略，不去听信你脑海中那些限制性的信念，你刚赚到了相当于平均工资三分之一的钱。如果你每周都这么做，3个月内你的收入就能超过大多数人的薪水。</p><p>与自由职业者不同的是，你在这个过程中还在积累受众。你的内容和推广并没有白费。随着你的成长，你在未来有潜力去卖新的东西。</p><p>重点是，你需要持续不断地<em>推广</em>你自己。</p><p>如果你不推广你的Offer，你就赚不到钱。</p><p>就这么简单。</p><h3 id="每天工作4小时-从0到100万美元-1" tabindex="-1">每天工作4小时，从0到100万美元 <a class="header-anchor" href="#每天工作4小时-从0到100万美元-1" aria-label="Permalink to &quot;每天工作4小时，从0到100万美元&quot;">​</a></h3><p>作为每天工作不超过4小时的一人企业，通向100万美元的路径：</p><ul><li>工作时间不要超过4小时</li><li>从客户工作开始</li><li>取得成果，赚到钱</li><li>积累你的受众</li><li>将你的工作产品化</li></ul><p>重复第3-5步，直到你赚到100万美元。</p><p>然后，不要停下来。</p><blockquote><p><strong>Koe定律：</strong><em>创造性工作会自我进化，在分配给它完成的时间内赚取更多收益</em>。这要求你具备创造力、不断成长，并获取技能来解决阻碍这种进化的难题。</p></blockquote><p>我们都听说过帕金森定律（Parkinson’s Law）。</p><p>即工作会膨胀，填满分配给它完成的时间。</p><p>但那只是第一层。你的工作膨胀了，但你的收入却没有。</p><p>每天工作4小时，这一直是我信奉了好一阵子的哲学。</p><p>人们没有意识到的是，借助技术，你可以工作同样的时间，却赚到你想赚的那么多钱。</p><p>问题在于，人们被商业意识形态困住了。</p><p>他们以自由职业者起步，这就是他们所知道的一切，他们对自由职业的偏好凌驾于其他模式之上，然后当他们无法逃脱“时饱时饥”的循环，只有勉强糊口的收入时，他们又去抱怨。</p><p>因为他们把自己认同为自由职业者，他们的思想就无法超越这一点去保持开放，从而察觉不到那些能让他们更好地利用自身技能组合发挥杠杆作用的机会。</p><p>他们离开了朝九晚五的工作去追求自由，结果却为自己创造了一个新的朝九晚五。</p><p>让我们来拆解一下Koe定律在实际步骤中是如何发挥作用的，从而实现从年入10万美元到月入10万美元的进化。</p><p><strong>阶段 1) 从客户工作开始</strong></p><p>作为一个没有受众的个人，接客户工作是最好的选择。</p><p>你可以使用手动的客户获取策略，向每个客户收取1000到10000美元以上的费用。</p><p>你只需要2-3个客户就能替代你原来的收入。</p><p>在我看来，最好跳过自由职业者阶段，直接进入上一节所述的教练、咨询或辅导阶段。</p><p>在4小时的时间框架内，你的时间分配如下：</p><ul><li>每天1小时寻找潜在新客户</li><li>每周3-5小时进行销售通话</li><li>每周2-4小时进行客户通话</li><li>每天1小时为受众和客户撰写内容</li><li>剩余时间用来处理以上各项中溢出的工作</li></ul><p>关键是在脑海中保持进化的意图，这样你就不会被困在这个阶段。</p><p><strong>阶段 2) 积累受众并进化一层</strong></p><p>作为一个以客户为主的业务，在每天4小时的工作时间里，你只能接这么多客户。</p><p>而如果你想保持一人单干，你需要找到那条能让你在不雇佣员工的情况下，依然维持同样工作时间的路线。</p><p>我已经为你发现了这条路线，所以你不必再经历数年的试错。</p><ul><li><strong>通过写作积累受众</strong>——现在先别把时间浪费在视频剪辑和图形设计上。利用<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">在社交媒体上写作和发布新闻邮件（newsletter）</a>来积累受众。如果你需要一个例子，去看看我的Instagram、LinkedIn和X。</li><li><strong>采用新的客户模型</strong>——创建一个项目、系列教程或课程大纲，并在小组教练的环境下接纳更多客户。这能把你的客户工作时间降到每周1-2小时。</li><li><strong>进化你的交付方式</strong>——稍微降一点价，去掉1对1通话这种吸时黑洞，引入群聊或社区，并在不削减任何价值的前提下，尝试重组你向客户交付成果的方式。</li></ul><p>现在，多亏了Koe定律，你把自己的收入潜力从每年10万美元提升到了30万-50万美元，而你工作的时间依然是那4小时。</p><p><strong>阶段 3) 随着你的受众增长实现产品化</strong></p><p>分发渠道 = 自由。</p><p>受众 = 分发渠道。</p><p>你可以随时将你的客户工作转化为数字产品，以获取额外收入（并且有可能吸引到那些在雇佣你之前需要了解更多信息的客户），但这在初期不会是你主要的收入来源。</p><p>在这第三个阶段，你将：</p><ul><li><strong>开设同期群课程</strong> —— 你的收费比以前低，但能接纳更多客户。多亏了你更庞大的受众群体，你在工作时间相同的情况下，赚得比小组客户模式更多。</li><li><strong>打造独立的数字产品</strong> —— 利用你在客户工作中的教学内容和成果，打造一个成功的产品。你只需构建一次，它就能在你睡觉时自动售卖，增加你的收入。</li><li><strong>想离开客户工作就离开</strong> —— 你的收入在刚开始时可能会有所下降，但这段新腾出来的时间可用于多元化平台布局、增加收入途径并提高受众增长的速度。</li></ul><p>同样，多亏了科伊定律（Koe’s Law），你已将自己的盈利潜力从每年 30 万美元提升到了每年 100 万美元以上。</p><p>这就是快速迭代发挥作用的地方。你必须脱离体力劳动，完全依靠你的创造力。</p><p>你的时间分配如下：</p><ul><li>每周 1-2 小时用来交付你的同期群课程</li><li>每天 2 小时用来写内容以推动增长</li><li>每天 1-2 小时用来构建能让你走得更远的项目</li></ul><p>你可以打造新产品，拓展一人企业（one-person business）之外的业务，或者干脆先享受一下生活，直到提前退休让你感到足够无聊，再重新开始有意义的构建。</p><p>你已经积累了大量的杠杆（leverage）和分发渠道，以至于你可以卖任何你想卖的东西。</p><p>雇佣一个团队来开发软件。</p><p>与产品开发者合作推出实体产品。</p><p>写一本书，巩固你在这个领域的历史地位。</p><p>然后把这一切再做一遍，因为金钱是一个工具，用来构建你想要但尚不存在的东西。无视那些告诉你不需要赚更多钱的人。尤其是当最终结果有利于社会的进化时。</p><p>– Dan</p><hr><p><a href="/en/letters/the-future-of-work-acquire-this-skill-stack">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',374))])}const x=a(u,[["render",g]]);export{A as __pageData,x as default};
